                out, err = p.communicate()
                rc = -999
            results.append({"rc": rc, "stdout": out.decode("utf-8", "replace"), "stderr": err.decode("utf-8", "replace")})
        tree = snapshot(box, set(scn.get("mtimes", [])), scn.get("dirs", "empty"), scn.get("nlink", False), set(scn.get("sorted", [])))
        return results, tree
    finally:
