def _lines(s):
    return s.split("\n")


def short_diff(got, want, label):
    d = list(difflib.unified_diff(_lines(want), _lines(got), "expected", "got", lineterm="", n=0))
    d = [l for l in d if not l.startswith(("---", "+++", "@@"))]
