            if tree[k].get("c") is not None and want[k].get("c") is not None and tree[k].get("c") != want[k].get("c"):
                msg += "\n" + short_diff(tree[k]["c"], want[k]["c"], "    first differing file")
        problems.append(msg)
    return problems


def main(repo=None):
    repo = repo or os.getcwd()
